// ── Parse & validate incoming request ──────────────────────────
const body = $json.body;

if (!body || typeof body !== 'object') {
  throw new Error('400: Request body is missing');
}

const destination  = (body.destination  || '').trim();
const location     = (body.location     || '').trim();
const startDate    = (body.startDate    || '').trim();
const endDate      = (body.endDate      || '').trim();
const style        = (body.style        || '').trim();
const dailyBudget  = (body.dailyBudget  || '').trim();
const interests    = Array.isArray(body.interests)
  ? body.interests
  : (body.interests ? [body.interests] : []);

if (!destination) {
  throw new Error('400: destination is required');
}

const dateStr = startDate && endDate
  ? `Visit dates: ${startDate} to ${endDate}.`
  : startDate ? `Arriving: ${startDate}.` : '';

const prompt = `You are a local travel expert and destination guide. Create a rich, practical exploration guide for a traveller visiting ${destination}.

${ location   ? `Their current base/location: ${location}.`        : '' }
${ dateStr }
${ style       ? `Travel style: ${style}.`                          : '' }
${ interests.length ? `Interests: ${interests.join(', ')}.`         : '' }
${ dailyBudget ? `Daily budget: ${dailyBudget}.`                    : '' }

Create a detailed exploration guide with these sections:

**Top Attractions:**
List 5-6 must-see places with a brief description and why it's worth visiting. Include a booking or info link where relevant using <a href="URL">Name</a> format.

**Hidden Gems:**
3-4 lesser-known spots that most tourists miss. Make these feel like insider tips.

**Food & Dining:**
5-6 specific restaurant or food experience recommendations. Include cuisine type, price range, and what to order.

**Day Plan (Sample Itinerary):**
A morning → afternoon → evening flow for one perfect day${ startDate ? ` starting ${startDate}` : '' }. Include estimated times.

**Getting Around:**
Best local transport options, tips on taxis vs rideshare vs walking, and any app recommendations.

**Local Tips:**
4-5 practical tips a local would tell you — customs, etiquette, safety, best times to visit sites, what to avoid.

Format each section heading in bold. Use bullet points for lists. Include real, working hyperlinks where possible (booking sites, Google Maps, official tourism pages). Keep the tone friendly and enthusiastic.`;

return [{ json: { destination, prompt } }];

// ── Validate OpenAI response & format output ────────────────────
const raw = $node['OpenAI'].json?.message?.content;

if (!raw || raw.trim() === '') {
  const reason = $node['OpenAI'].json?.message?.finish_reason || 'unknown';
  throw new Error(`OpenAI returned empty content. Finish reason: ${reason}`);
}

// Light HTML formatting for the frontend renderer
const html = raw
  .trim()
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n\n/g, '<br><br>')
  .replace(/\n- /g, '<br>• ')
  .replace(/\n/g, '<br>');

return [{ json: {
  result:      raw.trim(),
  resultHtml:  html,
  destination: $node['Parse & Build Prompt'].json.destination
}}];
